#include "shared/sea_nuclear_wave.hpp"
#include "metal_cpu_parallel.h"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <vector>
using namespace std;using Clock=chrono::steady_clock;static double ms(Clock::time_point a,Clock::time_point b){return chrono::duration<double,milli>(b-a).count();}
static SeaNuclearWaveSample eval(const vector<SeaNuclearWave>&w,const vector<int>&ids,float x,float z){SeaNuclearWaveSample r;for(int i:ids){auto q=EvaluateSeaNuclearWave(w[i],x,z);r.height+=q.height;r.slopeX+=q.slopeX;r.slopeZ+=q.slopeZ;r.foam=max(r.foam,q.foam);r.load=max(r.load,q.load);}CompressSeaNuclearWaveSample(r);return r;}
int main(){vector<SeaNuclearWave>w;for(int i=0;i<3600;i++){SeaNuclearWave a{float((i%24)*125-1500),float(((i/24)%20)*125-1250),0,0,true,10};a.Advance(1.f+float(i)/60);if(a.active)w.push_back(a);}constexpr int bins=32,binsize=192,step=48,nodes=bins*binsize/step+1;constexpr float minpos=-bins*binsize/2;vector<vector<int>> cells(bins*bins);auto t0=Clock::now();MetalCpuParallelFor(cells.size(),[&](size_t i)noexcept{int x=i%bins,z=i/bins;float l=minpos+x*binsize,b=minpos+z*binsize;auto&c=cells[i];for(int k=0;k<w.size();k++)if(SeaNuclearWaveIntersectsBox(w[k],l,b,l+binsize,b+binsize))c.push_back(k);});auto t1=Clock::now();size_t entries=0,capacity=0;for(auto &c:cells){entries+=c.size();capacity+=c.capacity();}printf("candidate_entries=%zu candidate_capacity_bytes=%zu snapshot_field_bytes=%zu wave_bytes=%zu\n",entries,capacity*sizeof(int),size_t(nodes)*nodes*sizeof(SeaNuclearWaveSample),w.size()*sizeof(SeaNuclearWave));vector<SeaNuclearWaveSample> field(nodes*nodes);MetalCpuParallelFor(nodes,[&](size_t z)noexcept{for(int x=0;x<nodes;x++){float px=minpos+x*step,pz=minpos+z*step;int bx=min(int(x*step/binsize),bins-1),bz=min(int(z*step/binsize),bins-1);field[z*nodes+x]=eval(w,cells[bz*bins+bx],px,pz);}});auto t2=Clock::now();vector<int> all(w.size());for(int i=0;i<w.size();i++)all[i]=i;double hsq=0,ssq=0,rawsq=0;float hm=0,sm=0,fm=0;int N=3000;for(int i=0;i<N;i++){float x=minpos+16+fmodf(i*197.53f,bins*binsize-32),z=minpos+16+fmodf(i*319.41f,bins*binsize-32);auto truth=eval(w,all,x,z);float gx=(x-minpos)/step,gz=(z-minpos)/step;int ix=gx,iz=gz;float u=gx-ix,v=gz-iz;auto a=field[iz*nodes+ix],b=field[iz*nodes+ix+1],c=field[(iz+1)*nodes+ix],d=field[(iz+1)*nodes+ix+1];auto lerp=[&](float aa,float bb,float cc,float dd){return (aa*(1-u)+bb*u)*(1-v)+(cc*(1-u)+dd*u)*v;};float h=lerp(a.height,b.height,c.height,d.height),sx=lerp(a.slopeX,b.slopeX,c.slopeX,d.slopeX),sz=lerp(a.slopeZ,b.slopeZ,c.slopeZ,d.slopeZ),foam=lerp(a.foam,b.foam,c.foam,d.foam);float he=abs(h-truth.height),se=hypotf(sx-truth.slopeX,sz-truth.slopeZ);hsq+=he*he;ssq+=se*se;rawsq+=truth.height*truth.height;hm=max(hm,he);sm=max(sm,se);fm=max(fm,abs(foam-truth.foam));}printf("active=%zu cells=%zu nodes=%zu index_ms=%.2f field_ms=%.2f height_rmse=%.4f height_max=%.4f signal_rms=%.4f slope_rmse=%.5f slope_max=%.5f foam_max=%.4f samples=%d\n",w.size(),cells.size(),field.size(),ms(t0,t1),ms(t1,t2),sqrt(hsq/N),hm,sqrt(rawsq/N),sqrt(ssq/N),sm,fm,N);}
